UPDATE group_folder
SET deleted_at = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND deleted_at IS NOT NULL

UPDATE group_folder
SET name = #{name},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND deleted_at IS NULL

UPDATE group_folder
SET deleted_at = #{deletedAt},
    updated_at = #{deletedAt}
WHERE deleted_at IS NULL
  AND id IN
#{id}
